// Signature & Token Verification
const headers = $input.first().json.headers || {};
const payload = $input.first().json.body || $input.first().json;
const aiSecret = process.env.AI_WEBHOOK_SECRET || 'ai_service_secret_token';
const providedSig = headers['x-ai-signature'] || headers['X-AI-Signature'];

if (providedSig && providedSig !== aiSecret) {
  throw new Error('Unauthorized: AI Webhook signature mismatch.');
}

// Payload Validation
if (!payload.match_id || !payload.source_post_id || !payload.matched_post_id || payload.similarity_score === undefined) {
  throw new Error('Invalid Payload: match_id, source_post_id, matched_post_id, and similarity_score are required.');
}

const similarityScore = parseFloat(payload.similarity_score);
const isHighConfidence = similarityScore >= 0.80 || payload.confidence === 'HIGH';

const normalizedData = {
  match_id: payload.match_id,
  source_post_id: payload.source_post_id,
  matched_post_id: payload.matched_post_id,
  child_name: payload.child_name || 'Unidentified Subject',
  similarity_score: similarityScore,
  similarity_percentage: (similarityScore * 100).toFixed(1) + '%',
  is_high_confidence: isHighConfidence,
  source_image_url: payload.source_image_url || 'https://kidnap-children.org/images/source.jpg',
  matched_image_url: payload.matched_image_url || 'https://kidnap-children.org/images/matched.jpg',
  matched_location: payload.matched_location || 'Unknown Location',
  guardian_email: payload.guardian_email || process.env.DEFAULT_ALERT_EMAIL || 'guardian@kidnap-children.org',
  guardian_phone: payload.guardian_phone || process.env.DEFAULT_ALERT_SMS || '+1234567890',
  match_details_url: payload.match_details_url || `https://kidnap-children.org/matches/${payload.match_id}`,
  detected_at: payload.detected_at || new Date().toISOString()
};

return [{ json: normalizedData }];

