const normalized = $("Verify AI Signature & Validate Match Payload").first().json;

if (normalized.is_high_confidence) {
  const emailRes = $("Urgent AI Match Email Notification").first().json;
  const smsRes = $("Urgent AI Match SMS Notification").first().json;
  const laravelRes = $("Sync High Match to Laravel Backend API").first().json;

  return [{
    json: {
      status: "success",
      match_id: normalized.match_id,
      confidence_level: "HIGH",
      similarity_percentage: normalized.similarity_percentage,
      email_status: emailRes ? "dispatched" : "failed",
      sms_status: smsRes ? "dispatched" : "failed",
      laravel_api_synced: !!laravelRes,
      message: `High confidence AI match #${normalized.match_id} processed and alerts dispatched.`
    }
  }];
} else {
  const candidateRes = $("Log Candidate Match to Laravel Backend API").first().json;
  return [{
    json: {
      status: "success",
      match_id: normalized.match_id,
      confidence_level: "LOW",
      similarity_percentage: normalized.similarity_percentage,
      candidate_logged: !!candidateRes,
      message: `Low confidence AI match #${normalized.match_id} logged as candidate candidate for manual review.`
    }
  }];
}
